const commander = require('../');

describe('negated option default independent of order', () => {
  test.each([
    ['--no-pepper first', (p) => p.option('--no-pepper').option('--pepper')],
    ['--pepper first', (p) => p.option('--pepper').option('--no-pepper')],
  ])('no implicit default when both defined, %s', (_, setup) => {
    const program = new commander.Command();
    setup(program);
    program.parse([], { from: 'user' });
    expect(program.opts().pepper).toBeUndefined();
  });

  test('lone --no-pepper defaults to true', () => {
    const program = new commander.Command();
    program.option('--no-pepper');
    program.parse([], { from: 'user' });
    expect(program.opts().pepper).toBe(true);
  });

  test.each([
    [
      '--pepper first',
      (p) => p.option('--pepper').option('--no-pepper', 'remove pepper', 'plain'),
    ],
    [
      '--no-pepper first',
      (p) => p.option('--no-pepper', 'remove pepper', 'plain').option('--pepper'),
    ],
  ])('explicit negated default used, %s', (_, setup) => {
    const program = new commander.Command();
    setup(program);
    program.parse([], { from: 'user' });
    expect(program.opts().pepper).toBe('plain');
  });
});
